<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useCajaChicaStore} from '@/stores/cajaChica';import {formatPen,limaDate,penCents,penDecimal} from '@/lib/financeMoney';import {cashMethodLabel} from '@/lib/financeCash';
const store=useCajaChicaStore(),day=ref(limaDate()),busy=ref(false),error=ref(''),notice=ref(''),available=ref(true),counted=ref(''),closeReason=ref(''),withdraw=ref(''),withdrawReason=ref(''),reopenReason=ref('');
const closeId=ref(crypto.randomUUID()),withdrawId=ref(crypto.randomUUID()),reopenId=ref(crypto.randomUUID());
const activeClosure=computed(()=>store.daily?.closures.find(c=>!c.reopened_at)),canWithdraw=computed(()=>day.value===limaDate()&&!activeClosure.value);
const difference=computed(()=>{try{return formatPen(penDecimal(penCents(counted.value)-penCents(String(store.daily?.closingCash??0))));}catch{return '—';}});
const money=(n:unknown)=>formatPen(String(n??0));
async function load(){busy.value=true;error.value='';try{await store.fetchDaily(day.value);available.value=true;}catch{available.value=false;store.daily=null;}finally{busy.value=false;}}
async function action(kind:'close'|'withdraw'|'reopen'){busy.value=true;error.value='';notice.value='';try{
 if(kind==='close'){await store.closeDay(closeId.value,day.value,penDecimal(penCents(counted.value)),closeReason.value.trim());closeId.value=crypto.randomUUID();notice.value='Cierre guardado con el efectivo contado y su diferencia.';}
 if(kind==='withdraw'){await store.ownerWithdraw(withdrawId.value,penDecimal(penCents(withdraw.value)),withdrawReason.value.trim());withdrawId.value=crypto.randomUUID();withdraw.value='';withdrawReason.value='';notice.value='Retiro del propietario registrado por separado.';}
 if(kind==='reopen'&&activeClosure.value){await store.reopenDay(reopenId.value,activeClosure.value.id,reopenReason.value.trim());reopenId.value=crypto.randomUUID();reopenReason.value='';notice.value='Caja reabierta; el cierre anterior queda en el historial.';}
 await store.fetchDaily(day.value);
 }catch(e){error.value=e instanceof Error?e.message:String((e as {message?:string})?.message??'No se pudo registrar la operación.');}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="surface p-5 mb-6 caja-finance" aria-labelledby="cash-finance-title"><div class="cash-heading"><h2 id="cash-finance-title" class="text-lg font-semibold">Cobranzas y cierre de efectivo</h2><label>Día en Perú<input v-model="day" type="date" :max="limaDate()" class="field-input" @change="load"></label><button class="btn-secondary" :disabled="busy" @click="load">Actualizar conciliación</button></div><p v-if="!available||!store.daily?.enabled" class="text-sm text-slate-600">La conexión de cobranzas con caja está pendiente de habilitación.</p><template v-else><div class="cash-metrics"><div>Saldo inicial<b>{{money(store.daily.openingCash)}}</b></div><div>Efectivo de cobranzas<b>{{money(store.daily.linkedCashCollections)}}</b></div><div>Gastos operativos<b>{{money(store.daily.operatingExpenses)}}</b></div><div>Retiros del propietario<b>{{money(store.daily.ownerWithdrawals)}}</b></div><div>Efectivo esperado<b>{{money(store.daily.closingCash)}}</b></div></div><p :class="Number(store.daily.unmatchedCash)===0?'text-green-700':'text-red-600'">{{Number(store.daily.unmatchedCash)===0?'Cobranzas de efectivo conciliadas.':'Diferencia entre cobranzas y caja: '+money(store.daily.unmatchedCash)}}</p><div class="cash-columns"><div><h3>Medios de pago</h3><p v-for="m in store.daily.methods??[]" :key="m.method">{{cashMethodLabel(m.method)}}: <b>{{money(m.net)}}</b><small v-if="m.method!=='cash'"> · separado del efectivo</small></p></div><div><h3>Administradoras responsables</h3><p v-for="c in store.daily.collectors??[]" :key="c.id+c.method">{{c.name}} · {{cashMethodLabel(c.method)}} · {{money(c.received)}}</p></div></div><div class="cash-columns"><form v-if="!activeClosure" @submit.prevent="action('close')"><h3>Cierre diario de efectivo</h3><label>Efectivo contado<input v-model="counted" inputmode="decimal" class="field-input" placeholder="0.00"></label><p>Diferencia: {{difference}}</p><label>Observación del arqueo<input v-model="closeReason" class="field-input" maxlength="500"></label><button class="btn-primary" :disabled="busy||!counted||closeReason.trim().length<5||Number(store.daily.unmatchedCash)!==0">Guardar cierre de efectivo</button></form><div v-else><h3>Caja cerrada</h3><p>Contado {{money(activeClosure.counted_cash)}} · Esperado {{money(activeClosure.expected_cash)}} · Diferencia {{money(activeClosure.difference)}}</p><label>Motivo de reapertura<input v-model="reopenReason" class="field-input" maxlength="500"></label><button class="btn-secondary" :disabled="busy||reopenReason.trim().length<5" @click="action('reopen')">Reabrir caja con auditoría</button></div><form @submit.prevent="action('withdraw')"><h3>Retiro del propietario</h3><p class="text-sm">Se registra como salida de efectivo separada de los gastos operativos.</p><label>Importe<input v-model="withdraw" inputmode="decimal" class="field-input" placeholder="0.00" :disabled="!canWithdraw"></label><label>Motivo<input v-model="withdrawReason" class="field-input" maxlength="500" :disabled="!canWithdraw"></label><button class="btn-secondary" :disabled="busy||!canWithdraw||!withdraw||withdrawReason.trim().length<5">Registrar retiro del propietario</button></form></div><details v-if="store.daily.closures.length"><summary>Historial de cierres</summary><p v-for="c in store.daily.closures" :key="c.id">{{new Date(c.created_at).toLocaleString('es-PE',{timeZone:'America/Lima'})}} · {{money(c.counted_cash)}} · {{c.reopened_at?'Reabierto':'Cerrado'}} · {{c.reason}}</p></details></template><p v-if="error" class="text-red-600" role="alert">{{error}}</p><p v-if="notice" class="text-green-700" role="status">{{notice}}</p></section></template>
<style scoped>.cash-heading{display:flex;align-items:end;gap:1rem;flex-wrap:wrap}.cash-heading h2{margin-right:auto}.cash-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1rem;margin:1rem 0}.cash-metrics b{display:block;font-size:1.2rem}.cash-columns{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:1.5rem;margin:1rem 0}.cash-columns h3{font-weight:600;margin:.5rem 0}.cash-columns label{display:block;margin:.5rem 0}.cash-columns button{margin-top:.7rem}</style>
